package com.kai.automusic;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import org.json.*;
public class PlayerService extends Service{MediaPlayer m;android.content.SharedPreferences p;int index=0,fail=0;boolean ready=false,want=false;String status="รอการชาร์จ";BroadcastReceiver power=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(!p.getBoolean("armed",false))return;if(Intent.ACTION_POWER_CONNECTED.equals(i.getAction())&&p.getBoolean("auto",true)){launch();play();}else if(Intent.ACTION_POWER_DISCONNECTED.equals(i.getAction())&&p.getBoolean("unplug",true))pause();}};
 Handler timer=new Handler(Looper.getMainLooper());Runnable checkpoint=new Runnable(){public void run(){remember();timer.postDelayed(this,3000);}};void remember(){if(m!=null&&ready)try{if(m.isPlaying()&&m.getCurrentPosition()>1000)fail=0;p.edit().putInt("position",m.getCurrentPosition()).putInt("duration",m.getDuration()).apply();}catch(Exception e){}}void launch(){if(p.getBoolean("launch",true))try{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}catch(Exception e){}}public void onCreate(){super.onCreate();p=getSharedPreferences("music",0);index=p.getInt("index",0);if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("music","ระบบเล่นเพลงอัตโนมัติ",NotificationManager.IMPORTANCE_LOW));IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);registerReceiver(power,f);timer.postDelayed(checkpoint,3000);}
 Notification notification(){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"music"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Kai Auto Music").setContentText(status).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();}void update(String s){status=s;p.edit().putString("playerStatus",s).putBoolean("playing",s.startsWith("กำลังเล่นเพลงที่")).apply();getSystemService(NotificationManager.class).notify(1,notification());}
 public int onStartCommand(Intent i,int flags,int id){startForeground(1,notification());String a=i==null?"ARM":i.getAction();if("BOOT".equals(a)){launch();Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(p.getBoolean("bootPlay",true)||(battery!=null&&battery.getIntExtra("plugged",0)!=0&&p.getBoolean("auto",true)))play();}else if("ARM".equals(a)){p.edit().putBoolean("armed",true).apply();Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null&&battery.getIntExtra("plugged",0)!=0&&p.getBoolean("auto",true))play();}else if("PLAY".equals(a))play();else if("PAUSE".equals(a))pause();else if("RESET".equals(a)){release();want=false;index=p.getInt("index",0);p.edit().putInt("position",0).apply();update("หยุดชั่วคราว");}else if("SELECT".equals(a)){fail=0;p.edit().putBoolean("stopAfter",false).apply();index=i.getIntExtra("index",0);p.edit().putInt("position",0).apply();want=true;load();}else if("SEEK".equals(a)){if(m!=null&&ready){m.seekTo(i.getIntExtra("ms",0));}}else if("PREV".equals(a)){fail=0;p.edit().putBoolean("stopAfter",false).apply();int n=songs().length();if(n>0){index=(p.getInt("index",index)+n-1)%n;p.edit().putInt("position",0).apply();want=true;load();}}else if("NEXT".equals(a)){fail=0;advance(true);}return START_STICKY;}
 JSONArray songs(){try{return new JSONArray(p.getString("songs","[]"));}catch(Exception e){return new JSONArray();}}void play(){want=true;fail=0;if(m!=null){if(ready){m.start();update("กำลังเล่นเพลงที่ "+(index+1));}return;}load();}void pause(){remember();want=false;if(m!=null&&ready&&m.isPlaying())m.pause();update("หยุดชั่วคราว");}void release(){p.edit().putInt("audioSession",-1).apply();p.edit().putBoolean("playing",false).apply();if(m!=null){m.release();m=null;}ready=false;}
 void load(){release();update("กำลังโหลดเพลง");JSONArray a=songs();if(a.length()==0){update("ไม่มีเพลงในเพลย์ลิสต์");return;}index=Math.max(0,Math.min(index,a.length()-1));p.edit().putInt("index",index).putInt("nextIndex",a.length()>1?(index+1+new java.util.Random().nextInt(a.length()-1))%a.length():index).apply();try{if(a.getString(index).startsWith("https://")){skipError();return;}m=new MediaPlayer();p.edit().putInt("audioSession",m.getAudioSessionId()).apply();m.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());m.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);m.setDataSource(this,Uri.parse(a.getString(index)));m.setOnPreparedListener(x->{ready=true;if(p.getBoolean("resume",true)){int pos=p.getInt("position",0);if(pos>0&&pos<x.getDuration())x.seekTo(pos);}if(want){x.start();update("กำลังเล่นเพลงที่ "+(index+1));}});m.setOnCompletionListener(x->{if(x!=m)return;if(p.getBoolean("stopAfter",false)){p.edit().putBoolean("stopAfter",false).putInt("position",0).apply();want=false;release();update("หยุดเมื่อเพลงจบแล้ว");}else advance(false);});m.setOnErrorListener((x,w,e)->{skipError();return true;});m.prepareAsync();}catch(Exception e){skipError();}}
 void skipError(){release();if(p.getBoolean("stopAfter",false)){p.edit().putBoolean("stopAfter",false).apply();want=false;update("เพลงเปิดไม่ได้ จึงหยุดตามคำสั่ง");return;}if(++fail>=songs().length()){want=false;update("ไม่มีไฟล์ที่เล่นได้");return;}p.edit().putInt("position",0).apply();index=(p.getInt("index",index)+1)%songs().length();new Handler(Looper.getMainLooper()).post(()->{if(want)load();});}void advance(boolean manual){index=p.getInt("index",index);int n=songs().length();if(n==0){release();return;}p.edit().putInt("position",0).apply();if(manual){want=true;p.edit().putBoolean("stopAfter",false).apply();}else fail=0;if(!manual&&!want)return;if(p.getBoolean("shuffle",false)&&n>1){int planned=p.getInt("nextIndex",-1);index=planned>=0&&planned<n&&planned!=index?planned:(index+1+new java.util.Random().nextInt(n-1))%n;}else if(index+1>=n&&!manual&&!p.getBoolean("repeat",true)&&!p.getBoolean("nonstop",true)){release();want=false;index=0;update("เล่นครบเพลย์ลิสต์แล้ว");return;}else index=(index+1)%n;load();}public IBinder onBind(Intent i){return null;}public void onDestroy(){remember();timer.removeCallbacks(checkpoint);unregisterReceiver(power);release();super.onDestroy();}}